      CommsLine(id: 'levelClear.h0', speaker: 'admiral', duration: 2.869, text: 'Sector secure. Outstanding flying.', mouth: '22222233332233322000333222244555533444333222', open: '02477467664467643211675444789989976888766321', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h1', speaker: 'sparrow', duration: 2.125, text: 'We did it! Sky\'s ours.', mouth: '22555444433222222444444444333333', open: '03786788855322337898889998756532', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h2', speaker: 'rook', duration: 2.342, text: 'Ha! Did you see that? Textbook.', mouth: '222200003334444444444222233333330000', open: '044211105678878889985335876556532110', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h3', speaker: 'wisp', duration: 2.207, text: 'Scopes clear. Good work, everyone.', mouth: '0000002233322000000000444333333222', open: '0137864366532110000377898555687432', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h4', speaker: 'nomad', duration: 2.816, text: 'Clean sweep. Proud to fly with you.', mouth: '2244444433444220000000444433333344444444222', open: '0378899867886421110006888876863789998876421', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h5', speaker: 'pip', duration: 2.874, text: 'That was amazing! Can we do it again?', mouth: '00004442222444444444444443322222444444455522', open: '01378874326888746889999877534787899889988532', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h6', speaker: 'kestrel', duration: 2.909, text: 'Sector\'s clear. That was beautiful flying.', mouth: '22222222222224444444444444444443333344443322', open: '02458536864378985327898646899997674688877632', emotion: 'triumphant'),
      CommsLine(id: 'levelClear.h7', speaker: 'sunny', duration: 2.399, text: 'Clean skies! That\'s the forecast I like.', mouth: '000444444443322000033333333333333300', open: '005897579987543216867678577467775321', signature: true, emotion: 'teasing'),
    ],
  ),
  'flawlessSector': CommsTriggerSpec(
    name: 'flawlessSector',
    priority: 6,
    cooldown: 10.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'flawlessSector.h0', speaker: 'admiral', duration: 3.933, text: 'Not a single ship lost in this sector. Textbook, all of you.', mouth: '334443334444444433443333333333332200000033333333344444333300', open: '058887657888778857887567765774554211005866376532789987765321', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h1', speaker: 'kestrel', duration: 3.46, text: 'Every wing accounted for. That\'s how it\'s done.', mouth: '3333333333344444333333223332200222444333444334443333', open: '0587667765689998557755336653211344798757888668886532', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h2', speaker: 'sunny', duration: 3.062, text: 'Zero losses! That was out of this world.', mouth: '2222333444445555443332220000443344433333333222', open: '0477765899988657885554421116887689877546776421', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessSector.h3', speaker: 'march', duration: 4.757, text: 'Bastion reporting. Every ground team is still standing. Thank you!', mouth: '333333333333333332200044444444444444333333444333444433220000444444444222', open: '057766566664666653211688876899987887776537898764788876432116887468886421', emotion: 'triumphant'),
    ],
  ),
  'flawlessVictory': CommsTriggerSpec(
    name: 'flawlessVictory',
    priority: 9,
    cooldown: 30.0,
    ttl: 6.0,
    mood: CommsMood.happy,
    chain: 2,
    lines: [
      CommsLine(id: 'flawlessVictory.h0', speaker: 'admiral', duration: 5.878, text: 'All hands, all ships, all squads. Every one of you is coming home. Fleet intact!', mouth: '33444433333333444443322222443333333322000000033444444444444444444442200044333444333222200', open: '06899767765536898877644327887645666542110006877888997788547888688874211688554897676424211', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h1', speaker: 'lindqvist', duration: 4.599, text: 'Beacon confirms. Full roster, no losses. I\'ve never seen it done.', mouth: '333334444334433333000000444443333333444444333332200000444334444333322', open: '057667867657876653211006889976775324899999767654321146788768874776532', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h2', speaker: 'rook', duration: 3.423, text: 'Perfect run! I\'m over the moon! All the moons!', mouth: '2222332233332224444555444444443322255544444332222200', open: '0463664467654268985788997888876542689988888764343211', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h3', speaker: 'sunny', duration: 3.09, text: 'Flawless! Somebody get this pilot a constellation!', mouth: '00004444333222224444444334444422233333333333300', open: '00278999755422378999877557898543267556665555321', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h4', speaker: 'pip', duration: 2.921, text: 'Everybody made it? Everybody? Best day ever!', mouth: '33334444444400004444444442224433444444444422', open: '05778778885321168889885323278766898578887532', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h5', speaker: 'kessler', duration: 2.546, text: 'Ground\'s all present! Drinks are on Bulwark tonight!', mouth: '224444444444332222333444444443333443322', open: '047887897688764368757898688997556787532', emotion: 'triumphant'),
    ],
  ),
  'flawlessRun': CommsTriggerSpec(
    name: 'flawlessRun',
    priority: 10,
    cooldown: 60.0,
    ttl: 8.0,
    mood: CommsMood.happy,
    chain: 3,
    lines: [
      CommsLine(id: 'flawlessRun.h0', speaker: 'admiral', duration: 5.971, text: 'Five tours. Not one ship, not one squad lost. The whole fleet salutes you, pilot.', mouth: '000444442223333322000000334444444422333344444444444444332200033344422332224444333334443322', open: '004898864446665542111058667998888534775789987478987888654321156379744774478887776578886532', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h1', speaker: 'nomad', duration: 4.422, text: 'Thirty years flying, and this is the run I\'ll tell stories about.', mouth: '0000443344444444444443332200004444444444444444444444455544444442200', open: '0006887788899987478887653211058898786889988789789987489888988764321', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h2', speaker: 'kestrel', duration: 5.268, text: 'Every wing, every crew, every squad. Fleet intact. Legendary.', mouth: '22244443333444444443333222443333333344332200005555220000333332200004444444444222', open: '03689987536888799877775437886766654787753211579965421168666764321368988999987432', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h3', speaker: 'sparrow', duration: 3.839, text: 'Not a scratch on the whole fleet! You\'re unbelievable!', mouth: '3344433333443334444444422222222000004444444445555555443333', open: '0688876647886658996478534787442111048974899888888687886532', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h4', speaker: 'mensah', duration: 3.426, text: 'Granite to air wing. Every trooper down here is cheering for you.', mouth: '3333333334433322000044444444444444443333444443332200', open: '0577745578876542110378987888899999987556888747764321', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h5', speaker: 'voss', duration: 3.794, text: 'Lantern here. All lights on, all teams home. Thank you, pilot!', mouth: '334444444433333444433444333344333333333300000033334444444', open: '058977878875327888876888753587677777765321106866757889953', emotion: 'triumphant'),
    ],
  ),
  'bossArrival': CommsTriggerSpec(
    name: 'bossArrival',
    priority: 9,
    cooldown: 30.0,
    ttl: 4.0,
    exchange: CommsSide.demon,
    lines: [
      CommsLine(id: 'bossArrival.h0', speaker: 'admiral', duration: 3.741, text: 'Carrier contact! Break its shield, then hit the hatch!', mouth: '222244444444444333330000000443334443322224444444444333222', open: '023789897688878753532112787877778987543278858576898566421', emotion: 'urgent'),
      CommsLine(id: 'bossArrival.h1', speaker: 'anvil', duration: 3.82, text: 'Here comes the big one. Shield first, then the core.', mouth: '0003333333333333322000004444444222233220000044443355555500', open: '0005656664657876643211058888986427766421113789886578985321', emotion: 'urgent'),
      CommsLine(id: 'bossArrival.h2', speaker: 'rook', duration: 3.713, text: 'Oh, that\'s huge. That is really, really huge.', mouth: '00044443333555522000444332222555443322244433330000222000', open: '00478987668887442115888754468999886533688776532145422110', emotion: 'urgent'),
      CommsLine(id: 'bossArrival.h3', speaker: 'wisp', duration: 3.229, text: 'Carrier field is up. Wear it down before the hatch opens.', mouth: '2224443333333330000000444444444433333333335555222', open: '0278985787776532110016898789886477687677656765321', emotion: 'urgent'),
      CommsLine(id: 'bossArrival.h4', speaker: 'lindqvist', duration: 3.242, text: 'Carrier in range. All fleet guns, support the pilot.', mouth: '2224433333333322000044333334444422334443344433222', open: '0367777677766643211688578568997634658885788865421', emotion: 'urgent'),
    ],
  ),
  'bossPhase': CommsTriggerSpec(
    name: 'bossPhase',
    priority: 6,
    cooldown: 10.0,
    ttl: 2.0,
    lines: [
      CommsLine(id: 'bossPhase.h0', speaker: 'admiral', duration: 2.468, text: 'It\'s changing form. Stay on the hatch.', mouth: '33333344444433333322222444444444333222', open: '06866688988856776642134799998897566421', emotion: 'urgent'),
      CommsLine(id: 'bossPhase.h1', speaker: 'wisp', duration: 2.316, text: 'Carrier\'s adapting. New pattern.', mouth: '00044433333223322000004443333355555', open: '02788876587446543211058986565555421', emotion: 'urgent'),
      CommsLine(id: 'bossPhase.h2', speaker: 'anvil', duration: 2.066, text: 'Field\'s down! Hit the core!', mouth: '0000444333444422000033225555222', open: '0006788766888643217857447986421', emotion: 'urgent'),
      CommsLine(id: 'bossPhase.h3', speaker: 'sparrow', duration: 3.184, text: 'It\'s getting angry. Good. Keep going.', mouth: '222233333333333000000000004442200000033344444222', open: '043257775677553211000000048974321100276479986421', emotion: 'urgent'),
      CommsLine(id: 'bossPhase.h4', speaker: 'kestrel', duration: 3.873, text: 'New form. Same weak spot. Find the hatch.', mouth: '00000044444444433300224455555533322000044444444443333222200', open: '00000689853789875321347899986477532110688899745776776444321', emotion: 'urgent'),
    ],
  ),
  'bossDefeated': CommsTriggerSpec(
    name: 'bossDefeated',
    priority: 7,
    cooldown: 20.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    exchange: CommsSide.fleet,
    lines: [
      CommsLine(id: 'bossDefeated.h0', speaker: 'admiral', duration: 3.381, text: 'The Carrier is down! All ships, the fleet salutes you.', mouth: '333344444444444444444444444433220000044334443333322', open: '065588889768999998532378888966421164577557886677532', emotion: 'triumphant'),
      CommsLine(id: 'bossDefeated.h1', speaker: 'rook', duration: 2.685, text: 'It\'s falling! It\'s actually falling!', mouth: '33322224444442222222233333333224444433222', open: '05542178988764364436876556777448999875321', emotion: 'triumphant'),
      CommsLine(id: 'bossDefeated.h2', speaker: 'anvil', duration: 2.435, text: 'Target destroyed. Hell of a run, pilot.', mouth: '2224444444444555522000444444433444422', open: '0358878546775888743216898888867888743', emotion: 'triumphant'),
      CommsLine(id: 'bossDefeated.h3', speaker: 'sparrow', duration: 2.095, text: 'Carrier down! Woohoo!', mouth: '00333344444443322224444444444222', open: '01677787888887642157997889987432', emotion: 'triumphant'),
      CommsLine(id: 'bossDefeated.h4', speaker: 'sunny', duration: 2.418, text: 'Carrier down! Looks like it\'s lights out for them.', mouth: '0004444444443322223333344444333333222', open: '0068999999987533647785788688566776421', signature: true, emotion: 'teasing'),
    ],
  ),
  'defeat': CommsTriggerSpec(
    name: 'defeat',
    priority: 10,
    cooldown: 30.0,
    ttl: 4.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'defeat.h0', speaker: 'admiral', duration: 5.287, text: 'All ships totalled, but every pilot is safe. Regroup at base. We go again.', mouth: '00004444433333333322000004444444555333332200000000444333333332200004444444442200', open: '00068987876557877542110168988688888766653211001786887674676654211068899888764211', emotion: 'exhausted'),
      CommsLine(id: 'defeat.h1', speaker: 'admiral', duration: 3.928, text: 'That\'s the last reserve. Bring it home, pilot. We\'ll launch again.', mouth: '33333344443333333220000000000444444333333220055544433333322', open: '06853679987566765421110000006898899777775321168998777776532', emotion: 'exhausted'),
      CommsLine(id: 'defeat.h2', speaker: 'lindqvist', duration: 4.799, text: 'Recovery has your pod. Rest up. The fleet will be ready when you are.', mouth: '333344433333333333333220000033334442200000000000044444444444445554444422', open: '056688777655777755775321100277667874321100000054588678889998789999887532', emotion: 'exhausted'),
    ],
  ),
  'groundForceSighted': CommsTriggerSpec(
    name: 'groundForceSighted',
    priority: 5,
    cooldown: 18.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundForceSighted.h0', speaker: 'admiral', duration: 3.336, text: 'Ground enemies incoming! Ground forces ahead!', mouth: '000044444444443344334433220000044444443333334433300', open: '024789887899985688678765321102689964787767677875321', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h1', speaker: 'wisp', duration: 2.895, text: 'Demon ground troops below. Marking them now.', mouth: '33444444444333333333332200004433333333333222', open: '06888887898767553677764211058975666667765321', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h2', speaker: 'anvil', duration: 2.656, text: 'Movement on the ground. Brood infantry.', mouth: '2224444333333332200000044555333333332200', open: '0378788677757864321102689998757856554321', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h3', speaker: 'kessler', duration: 3.006, text: 'Bulwark here. Brood walkers moving on our line!', mouth: '5555552222220000044444333355544334444444442200', open: '0587774244321101588789778789888778899888764321', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h4', speaker: 'march', duration: 4.119, text: 'Bastion to air wing. Enemy armor on the ground, your side of the ridge.', mouth: '33443333333333333220000444444444444333333334444444433333322222', open: '05787678764666665432116899888998888677776468987888767676534321', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h5', speaker: 'mensah', duration: 3.03, text: 'Granite here. They\'re massing below you. Lots of them.', mouth: '2223322222000044444433355544433222244444332200', open: '0246542322110477778876777789875322589867753211', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h6', speaker: 'kessler', duration: 2.848, text: 'Enemy armor on the ridge! Big ones!', mouth: '2224443344444334444444443333000005555333222', open: '0478887789898568988768986553211687788765421', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h7', speaker: 'voss', duration: 2.129, text: 'Lantern sees walkers coming over the rocks.', mouth: '33444444444444433444444444433333', open: '05897887877887777888888789855532', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h8', speaker: 'march', duration: 3.673, text: 'Bastion to all teams, advance. Air wing has our backs.', mouth: '33444444433444444443332233333222222244444444443332222200', open: '05888678766898778877653266776444321689999988887654233211', emotion: 'stern'),
      CommsLine(id: 'groundForceSighted.h9', speaker: 'mensah', duration: 2.394, text: 'Granite\'s moving up. Stay close, everyone.', mouth: '003344444444442222222334444433333322', open: '005787579899874322378658878876777532', emotion: 'calm'),
      CommsLine(id: 'groundForceSighted.h10', speaker: 'kessler', duration: 2.387, text: 'Bulwark advancing. Keep your heads down.', mouth: '555555544443332200000333444433333222', open: '068999788777654321100574888976655321', emotion: 'calm'),
      CommsLine(id: 'groundForceSighted.h11', speaker: 'wisp', duration: 2.697, text: 'Armor signatures on the ground. Heavy ones.', mouth: '33444333333333333444333300000444444333222', open: '06899776655667775898765321105888887765321', emotion: 'urgent'),
    ],
  ),
  'groundForceInRange': CommsTriggerSpec(
    name: 'groundForceInRange',
    priority: 6,
    cooldown: 14.0,
    ttl: 2.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundForceInRange.h0', speaker: 'sparrow', duration: 2.542, text: 'Ground targets in range. Fire!', mouth: '000444433333355544433333000000334442200', open: '025899866767468998865453211000678864211', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h1', speaker: 'rook', duration: 2.251, text: 'Strafing run! Hit them now!', mouth: '0000443344334443330000222444443322', open: '0116885687668886532147437899997632', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h2', speaker: 'anvil', duration: 2.541, text: 'They\'re under your guns. Take the shot.', mouth: '222444444443344333322000443344444220000', open: '034797788776688757743215895789997432110', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h3', speaker: 'voss', duration: 3.098, text: 'Lantern here. They\'re right under you. Light them up!', mouth: '22444444443322222334444444433220000005554444400', open: '04888887777642178778988877776421102688588985321', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h4', speaker: 'mensah', duration: 1.736, text: 'You\'re right over them. Bring the rain!', mouth: '223344444332224444444433300', open: '025688998754248898999875321', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h5', speaker: 'kessler', duration: 1.961, text: 'They\'re close enough to bite! Hit them!', mouth: '222244444333344422000333332200', open: '045378778667489743211663764321', emotion: 'urgent'),
      CommsLine(id: 'groundForceInRange.h6', speaker: 'march', duration: 3.003, text: 'Contact at the wire. Air wing, engage!', mouth: '0003333322222333333222244444444444444444222000', open: '0036766742453556655421689887645888999876443211', emotion: 'urgent'),
    ],
  ),
  'allyUnderAttack': CommsTriggerSpec(
    name: 'allyUnderAttack',
    priority: 7,
    cooldown: 14.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    group: 'ground',
    exchange: CommsSide.fleet,
    lines: [
      CommsLine(id: 'allyUnderAttack.h0', speaker: 'kessler', duration: 2.362, text: 'We\'re pinned down. Need air support!', mouth: '002222333333220003334444433444444222', open: '014214666665421105778887876899985421', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h1', speaker: 'kessler', duration: 3.037, text: 'Please shoot these enemies! They\'re all over us!', mouth: '2233333333333333444333000004444445554444422200', open: '0256666666356547888753216857899868989998544321', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h2', speaker: 'voss', duration: 2.565, text: 'Pick up some homing missiles! We need them off our backs!', mouth: '333333444444444433355555444444444333222', open: '056867888788878865347997899787888555421', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h3', speaker: 'march', duration: 4.001, text: 'Bastion to air wing, my teams are taking fire. Requesting support!', mouth: '3333333333444444444444444433333333444422000222224444444444400', open: '0577677757888888537887788866757747888742117437868877647985321', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h4', speaker: 'mensah', duration: 2.934, text: 'Granite\'s surrounded! Anything you\'ve got, send it down!', mouth: '000333223333332223333444334443334443344444222', open: '004665346577764215774887758985548786589985321', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h5', speaker: 'voss', duration: 2.666, text: 'Lantern to air wing, we\'re taking fire! Help!', mouth: '3344444444444433333333334444422000444400', open: '0589878878988877668666478888642117885321', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h6', speaker: 'march', duration: 3.169, text: 'Bastion is under heavy fire! We need you now!', mouth: '223333333333333333333344332200005555544444444222', open: '046764565566653576753678764321489899988988876421', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h7', speaker: 'mensah', duration: 2.069, text: 'Granite\'s taking a beating! Help!', mouth: '22244443333222444442200044555500', open: '02788547765433777864211789974211', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h8', speaker: 'kessler', duration: 3.013, text: 'Taking fire, taking fire! Air support!', mouth: '0033333344332223333334444440000044333333322200', open: '0256576588763447556537887532110688666457744211', emotion: 'panicked'),
    ],
  ),
  'allySaved': CommsTriggerSpec(
    name: 'allySaved',
    priority: 5,
    cooldown: 12.0,
    ttl: 3.0,
    mood: CommsMood.happy,
    group: 'ground',
    lines: [
      CommsLine(id: 'allySaved.h0', speaker: 'kessler', duration: 2.659, text: 'That did it! Thanks for the cover, flyer!', mouth: '0004433344442200004433344333333333333322', open: '0258965688763211068876688658787467767642', emotion: 'warm'),
      CommsLine(id: 'allySaved.h1', speaker: 'voss', duration: 2.088, text: 'They\'re scattering! We owe you one!', mouth: '33444444444333333444444444333222', open: '05786799988765326879989888765321', emotion: 'warm'),
      CommsLine(id: 'allySaved.h2', speaker: 'march', duration: 2.563, text: 'Pressure\'s off. Bastion thanks you, air wing.', mouth: '000004444444400044444444444333444455522', open: '006778889885321789878889887767887887642', emotion: 'warm'),
      CommsLine(id: 'allySaved.h3', speaker: 'mensah', duration: 2.76, text: 'Granite\'s clear! Solid as a rock, thanks to you.', mouth: '334444222443322222444444444422222222333300', open: '058987436887532136899978898642543234665321', signature: true, emotion: 'teasing'),
      CommsLine(id: 'allySaved.h4', speaker: 'voss', duration: 2.274, text: 'Lantern is clear. Beautiful shooting!', mouth: '33444444444443322000444444444433222', open: '05898888747887532126898688888876421', emotion: 'warm'),
      CommsLine(id: 'allySaved.h5', speaker: 'march', duration: 2.251, text: 'That\'s the air wing I know. Thank you.', mouth: '3344444444444444443333000443333222', open: '0688748789888888887653214885565432', emotion: 'warm'),
      CommsLine(id: 'allySaved.h6', speaker: 'mensah', duration: 2.534, text: 'You saved our skins, flyer. I owe you.', mouth: '003334444444444333333332222224443322200', open: '025767998997578653555553215778986543211', emotion: 'warm'),
      CommsLine(id: 'allySaved.h7', speaker: 'kessler', duration: 2.795, text: 'Whew. That was close. Thanks, friend!', mouth: '000000000332200033333333222200000333333322', open: '011100378753211066764576443211068766777532', emotion: 'exhausted'),
      CommsLine(id: 'allySaved.h8', speaker: 'voss', duration: 1.597, text: 'You\'re a lifesaver up there!', mouth: '334444444444444444444422', open: '058998899768878853787642', emotion: 'excited'),
    ],
  ),
  'allyRetreated': CommsTriggerSpec(
    name: 'allyRetreated',
    priority: 6,
    cooldown: 20.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    group: 'ground',
    lines: [
      CommsLine(id: 'allyRetreated.h0', speaker: 'kessler', duration: 2.54, text: 'I\'m totalled! Going back to base!', mouth: '334444444433220004444444422222332222000', open: '058886468875321147899999642364653443211', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h1', speaker: 'voss', duration: 3.833, text: 'Lantern\'s rig is totalled. We\'re limping home. Cover the gap!', mouth: '3344444444444433334443322000004444444444333333444444444400', open: '0589888878987457657777532110068998888888753227898789985321', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h2', speaker: 'march', duration: 4.914, text: 'Bastion\'s command track is wrecked. Pulling back to base. Hold the line for us!', mouth: '33444444334444433333333333332220000444444333333333000004444444444333322222', open: '05887688757888876776467667753421127899997666776553211058989988874665544321', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h3', speaker: 'mensah', duration: 3.002, text: 'Granite\'s crumbled! Heading back to base to patch up!', mouth: '2233332222255552222333443333444444444444444400', open: '0256764215888864214666896657897453587689985321', signature: true, emotion: 'teasing'),
      CommsLine(id: 'allyRetreated.h4', speaker: 'admiral', duration: 3.528, text: 'A ground team is heading home for repairs. Cover their retreat.', mouth: '33344444444433444444433333443333300000444444333333333', open: '06789998888865889899957766787655321115889887766764532', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h5', speaker: 'kessler', duration: 3.361, text: 'Bulwark\'s rig is smoking. Limping back to base!', mouth: '000555533334444333333322200000004444444443333222000', open: '015888966578964655557743211000058888798646565322110', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h6', speaker: 'voss', duration: 3.223, text: 'I\'m totalled, going back to base! Keep them busy!', mouth: '3344444444332200044443334443333000033344444443333', open: '0689876888774321788897778987653211375378788787532', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h7', speaker: 'mensah', duration: 2.666, text: 'Tracks are gone. Granite\'s heading home for repairs!', mouth: '0000333344332200044444455553333344442222', open: '0168554678754211689768888985787689864321', emotion: 'exhausted'),
      CommsLine(id: 'allyRetreated.h8', speaker: 'march', duration: 3.219, text: 'I\'m totalled, going back to base. You have the field.', mouth: '2222334443322224444433344333222224444444444332200', open: '0467668987532158889856678766432378998774787653211', emotion: 'exhausted'),
    ],
  ),
  'groundUnitDestroyed': CommsTriggerSpec(
    name: 'groundUnitDestroyed',
    priority: 2,
    cooldown: 14.0,
    ttl: 2.0,
    chance: 0.6,
    mood: CommsMood.happy,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundUnitDestroyed.h0', speaker: 'kessler', duration: 2.34, text: 'Bulwark here. Splashed a walker. Line\'s holding.', mouth: '334444443322222444444333334444442200', open: '058889646642237886889765358887864321', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h1', speaker: 'voss', duration: 2.675, text: 'Lantern got one! Scratch one brood crawler.', mouth: '22444444444333332222222333333444444433222', open: '03788787788677653214278766776896478776421', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h2', speaker: 'march', duration: 4.304, text: 'Bastion reports another contact down. This sector is ours.', mouth: '33443334443333344443333333333332200044444443333344433444444443322', open: '05887678746765779885566565466664211489886885787789866899999876532', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h3', speaker: 'mensah', duration: 2.464, text: 'Granite here. One less demon on the ground.', mouth: '0033332222220000444433444444444443322', open: '0157764454321126889975899888689987532', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h4', speaker: 'rook', duration: 2.059, text: 'Ground crews are crushing it down there!', mouth: '0004444444422444444433333333222', open: '0168867888544798899867776665321', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h5', speaker: 'kessler', duration: 1.551, text: 'Got one! Scratch that walker!', mouth: '334444444444444443332200', open: '058799876886777885554211', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h6', speaker: 'voss', duration: 2.015, text: 'Lantern\'s team took out a crawler. Whoo!', mouth: '2233333333222332233322255544422', open: '0366565366444653455542168998642', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h7', speaker: 'march', duration: 3.077, text: 'Enemy unit destroyed. Good shooting, Bastion.', mouth: '33444455554444333333332200044444444333333333222', open: '05899998888854676677764211788789987777646665321', emotion: 'calm'),
      CommsLine(id: 'groundUnitDestroyed.h8', speaker: 'mensah', duration: 1.782, text: 'Rock solid. Another one down.', mouth: '223333444422233355544443333', open: '036755898642257888998987532', emotion: 'teasing'),
      CommsLine(id: 'groundUnitDestroyed.h9', speaker: 'kessler', duration: 2.209, text: 'Bulwark\'s still standing and they aren\'t.', mouth: '2244443344444444443344443344422000', open: '0489987588678999985688886787543211', emotion: 'teasing'),
      CommsLine(id: 'groundUnitDestroyed.h10', speaker: 'voss', duration: 2.252, text: 'Down it goes! Next!', mouth: '2222444444444433220000004444442222', open: '0336888878999876421100057887454421', emotion: 'excited'),
      CommsLine(id: 'groundUnitDestroyed.h11', speaker: 'sparrow', duration: 2.282, text: 'Nice work down there, ground team!', mouth: '33444334433444443322224444333333222', open: '05898678856888887642147898666765321', emotion: 'warm'),
    ],
  ),
  'groundPressureRising': CommsTriggerSpec(
    name: 'groundPressureRising',
    priority: 5,
    cooldown: 30.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundPressureRising.h0', speaker: 'kessler', duration: 2.549, text: 'They\'re pushing harder. Could use some help soon.', mouth: '222233333344444222222334444443333555522', open: '021366654689997432247778888897667898642', emotion: 'urgent'),
      CommsLine(id: 'groundPressureRising.h1', speaker: 'voss', duration: 2.93, text: 'More of them every minute down here. Keep an eye on us.', mouth: '33444444334444444444444442200334444444333222', open: '05899888678888998888678874211578899988765432', emotion: 'urgent'),
      CommsLine(id: 'groundPressureRising.h2', speaker: 'march', duration: 3.756, text: 'Bastion to air wing. Pressure is building on our line.', mouth: '334444444444444444433220000004444444444444443344444332222', open: '058886799877478887776432110278879887689898787788888764321', emotion: 'urgent'),
      CommsLine(id: 'groundPressureRising.h3', speaker: 'mensah', duration: 2.636, text: 'Granite\'s starting to crack. Not yet, but soon.', mouth: '0033333333332233220004433444444222255555', open: '0057775366653255432147976898545325886421', emotion: 'urgent'),
    ],
  ),
  'groundPressureHigh': CommsTriggerSpec(
    name: 'groundPressureHigh',
    priority: 6,
    cooldown: 24.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundPressureHigh.h0', speaker: 'kessler', duration: 3.327, text: 'We can\'t hold much longer! Need air support now!', mouth: '22222233443333333444444223334444333344333444445555', open: '04425777897785457887885325778987763688557899998642', emotion: 'panicked'),
      CommsLine(id: 'groundPressureHigh.h1', speaker: 'voss', duration: 2.486, text: 'Lantern\'s line is buckling! Help us!', mouth: '22444443344444222233444422222244433222', open: '04788777788887437857888642278588865321', emotion: 'panicked'),
      CommsLine(id: 'groundPressureHigh.h2', speaker: 'march', duration: 3.293, text: 'All air units, the ground line is about to break!', mouth: '22244444444433222333344444444333333443333344442200', open: '04788678878876321575589988888666637887764589953211', emotion: 'panicked'),
      CommsLine(id: 'groundPressureHigh.h3', speaker: 'mensah', duration: 2.786, text: 'Granite\'s crumbling fast! Send everything you\'ve got!', mouth: '223332222555333344422000004444444433444444', open: '025674325767764788743211167998688875899853', emotion: 'panicked'),
      CommsLine(id: 'groundPressureHigh.h4', speaker: 'admiral', duration: 3.451, text: 'The ground line is failing. Give them cover, pilot.', mouth: '3333444444433332224444444220000005555334443344433322', open: '0545899998877653268888876432110066898658895688876532', emotion: 'panicked'),
    ],
  ),
  'groundBreakthrough': CommsTriggerSpec(
    name: 'groundBreakthrough',
    priority: 8,
    cooldown: 14.0,
    ttl: 2.5,
    mood: CommsMood.worried,
    group: 'ground',
    urgent: true,
    lines: [
      CommsLine(id: 'groundBreakthrough.h0', speaker: 'admiral', duration: 3.809, text: 'Breakthrough! Enemy ground units in firing range!', mouth: '2244422224444422000044444334444444443333334444444433333222', open: '0478632478897532110588887658999888986785378888888877665321', emotion: 'panicked'),
      CommsLine(id: 'groundBreakthrough.h1', speaker: 'kessler', duration: 2.213, text: 'They broke through! Missiles coming your way!', mouth: '3333333344444444444334444444444222', open: '0567864588532378788657889989987421', emotion: 'panicked'),
      CommsLine(id: 'groundBreakthrough.h2', speaker: 'march', duration: 2.698, text: 'Breach in the line! They\'re targeting the air wing!', mouth: '00044444444433222223334444443344444433222', open: '00587788888776421687768889997688988865321', emotion: 'panicked'),
      CommsLine(id: 'groundBreakthrough.h3', speaker: 'kestrel', duration: 3.05, text: 'Ground breakthrough. Watch for missiles from below!', mouth: '0004444443333222555544333344444334444444332200', open: '0047999987776346644788553789878667788887654211', emotion: 'panicked'),
      CommsLine(id: 'groundBreakthrough.h4', speaker: 'anvil', duration: 3.007, text: 'They\'re through the line. Dodge the ground fire!', mouth: '2233322333333332200000000444333444433444442200', open: '0267644665556653211000006898675899866888763211', emotion: 'panicked'),
    ],
  ),
  'broodTaunt': CommsTriggerSpec(
    name: 'broodTaunt',
    priority: 4,
    cooldown: 35.0,
    ttl: 4.0,
    chance: 0.6,
    exchange: CommsSide.demon,
    lines: [
      CommsLine(id: 'broodTaunt.h0', speaker: 'admiral', duration: 2.557, text: 'Laugh while you can. We\'re coming for you.', mouth: '222444444433333322000033344444444444422', open: '047895899866776532110166579985899998642', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h1', speaker: 'rook', duration: 3.222, text: 'Yeah, yeah. Big talk from a flying gargoyle.', mouth: '0022220000333220000443344443333334444444433322200', open: '0244432110565321117897689985776468999888766543211', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h2', speaker: 'sparrow', duration: 1.994, text: 'Was that a threat? Cute.', mouth: '333344433344332200000004443322', open: '068788875788553211000037887742', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h3', speaker: 'anvil', duration: 2.606, text: 'Keep growling. It won\'t save you.', mouth: '0003322222444333000000333444444443322000', open: '0136743336898753211000566899788997543211', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h4', speaker: 'kestrel', duration: 3.311, text: 'Kestrel to brood: we heard you. Come and try it.', mouth: '00000033333333355554433444443330000044433444422000', open: '00000277558677689978857887776532112689877888642110', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h5', speaker: 'sunny', duration: 2.761, text: 'Somebody needs a breath mint. And a new career.', mouth: '000444444444433332220000044444444333333222', open: '006889998868855664321100489878897577765421', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h6', speaker: 'pip', duration: 2.825, text: 'Was that at me? Okay. Okay! I\'m not scared!', mouth: '2224444444422333444422233444444443334444444', open: '0458887888642575898534767898689987768987532', emotion: 'excited'),
      CommsLine(id: 'broodTaunt.h7', speaker: 'nomad', duration: 2.51, text: 'I\'ve heard scarier thunderstorms, friend.', mouth: '33444444433344444433444433555553333222', open: '05886899876478988865898866776546666421', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h8', speaker: 'wisp', duration: 3.171, text: 'Translation: they\'re nervous. Good.', mouth: '224444444443322000044444333322000000000044333000', open: '047888998777632110489998766532110000000488553211', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h9', speaker: 'lindqvist', duration: 2.463, text: 'Noted. Logged. Ignored.', mouth: '3344333333000000444422200003334443333', open: '0589776553211005898543211006578876532', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h10', speaker: 'march', duration: 2.396, text: 'Bastion hears you, brood. We\'re not moving.', mouth: '334444444444443344442224444555443322', open: '058887787887786788874268997898877642', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h11', speaker: 'kessler', duration: 3.269, text: 'Bulwark to brood: come down here and say that.', mouth: '00033335554433444444422224444444444444333444333222', open: '00477558989855876798743378878998789777665788775321', emotion: 'teasing'),
    ],
  ),
  'playerRespawn': CommsTriggerSpec(
    name: 'playerRespawn',
    priority: 5,
    cooldown: 6.0,
    ttl: 4.0,
    delay: 0.6,
    lines: [
      CommsLine(id: 'playerRespawn.h0', speaker: 'admiral', duration: 3.409, text: 'Spare ship on deck four, launch! You\'re clear, pilot.', mouth: '2222444444444444444422244333322000000000443333332200', open: '0246888868989853787642588756642110068547887677774321', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h1', speaker: 'lindqvist', duration: 3.135, text: 'Reserve fighter is hot. Welcome back to the fight.', mouth: '334444443333333333222200000444444433333333222200', open: '057799747766665457424321106886899955564676444321', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h2', speaker: 'kestrel', duration: 3.56, text: 'New ship, same pilot. Form up on me.', mouth: '000004444444422222444433333220000000004444334443332200', open: '000058998778632135899777655421110000068999778887764211', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h3', speaker: 'nomad', duration: 3.591, text: 'Fresh paint, fresh engines. Take it easy for a second.', mouth: '000044444444220000444444433322000333444444443333332200', open: '002787479985432117879998876542111677888888777785654321', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h4', speaker: 'anvil', duration: 2.145, text: 'Back in the air. Shake it off.', mouth: '222443334444422000004433333220000', open: '036875677898632110068977765321100', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h5', speaker: 'sparrow', duration: 2.686, text: 'There you are! Don\'t scare me like that.', mouth: '22244444444333002244433333444444433322200', open: '03788878987653213489875457789987456533211', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h6', speaker: 'rook', duration: 2.408, text: 'New ship smell! Try not to scratch this one.', mouth: '2255544433333322224444334433333222200', open: '0378988966787642378988767876555433211', emotion: 'teasing'),
      CommsLine(id: 'playerRespawn.h7', speaker: 'wisp', duration: 3.599, text: 'Reserve ship launched. Shields at full. Blink and go.', mouth: '333444444433443333220000003355544443333333444444443322', open: '057899888856887556432110005789888537775324887676877532', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h8', speaker: 'sunny', duration: 2.048, text: 'Rise and shine! Look who\'s back.', mouth: '3344443344444440000004444442200', open: '0589787789988532116858868874211', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h9', speaker: 'pip', duration: 2.044, text: 'You\'re back! I knew you\'d be back!', mouth: '3333444422000055544433333322000', open: '0587898742115899989877777532110', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h10', speaker: 'march', duration: 2.645, text: 'Bastion sees your new ship. We\'re still with you.', mouth: '3344444444444444443333222244444443333222', open: '0688867887788788887676423788788885565432', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h11', speaker: 'kessler', duration: 1.971, text: 'Ground\'s glad to see you up there again!', mouth: '000444334444333444433333333322', open: '006898778988767877456766666632', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h12', speaker: 'voss', duration: 2.829, text: 'Lantern lights for the new ship. Go get them.', mouth: '2244444444433344444444400000003344333322000', open: '0479888899757788877885321100017788577642111', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h13', speaker: 'mensah', duration: 2.378, text: 'Granite here. Solid launch, flyer.', mouth: '224444222200000444444332200004443333', open: '048886444321127889888754211158986532', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h14', speaker: 'admiral', duration: 4.118, text: 'Recovery has your pod. Your reserve is ready. Fly.', mouth: '33334444444444444333332200000445554444444443322000000004443333', open: '06868888886788787557764211006899989986877887542111000048876532', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h15', speaker: 'nomad', duration: 4.331, text: 'Every great pilot loses a ship. Great ones get back up.', mouth: '33444444444422244444455544444444422000000000443344444433334444222', open: '06888888788743378887478998888789743211000006886777878857857886421', emotion: 'warm'),
    ],
  ),
  'groundMissileLaunch': CommsTriggerSpec(
    name: 'groundMissileLaunch',
    priority: 6,
    cooldown: 12.0,
    ttl: 1.5,
    chance: 0.5,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundMissileLaunch.h0', speaker: 'kessler', duration: 1.946, text: 'Missile up! It\'s going for you!', mouth: '222444444442223333444433322000', open: '036887889964236547899856543211', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h1', speaker: 'voss', duration: 2.044, text: 'Launch from the ground! Break off!', mouth: '3344433444444442200044444442200', open: '0589867877888764211687889864211', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h2', speaker: 'anvil', duration: 2.198, text: 'Missile from below. Move.', mouth: '222444433334444422000004455552200', open: '047898856778887632110058999753211', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h3', speaker: 'wisp', duration: 2.637, text: 'Ground launch detected. Sidestep it.', mouth: '3344444443333332233220000000044433333222', open: '0589988887756574355421100003689765535432', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h4', speaker: 'mensah', duration: 1.8, text: 'Granite sees a missile! Watch out!', mouth: '222444433444433222223344422', open: '037875466789865421686688642', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h5', speaker: 'sparrow', duration: 1.316, text: 'Something\'s coming up at you!', mouth: '22244443344433222200', open: '03787997788756443211', emotion: 'panicked'),
    ],
  ),
  'groundPressureEased': CommsTriggerSpec(
    name: 'groundPressureEased',
    priority: 4,
    cooldown: 30.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundPressureEased.h0', speaker: 'march', duration: 1.831, text: 'We\'re pushing them back! Keep it up!', mouth: '2222333444444422000000444444', open: '0453777888788742111747899853', emotion: 'triumphant'),
      CommsLine(id: 'groundPressureEased.h1', speaker: 'kessler', duration: 2.346, text: 'They\'re running! Bulwark advances!', mouth: '000044444444220005555555444433222000', open: '021687899886421237878687788765433211', emotion: 'excited'),
      CommsLine(id: 'groundPressureEased.h2', speaker: 'voss', duration: 2.532, text: 'Line\'s holding. We\'ve got room to breathe.', mouth: '22444444443333330000004444444444444222', open: '04899874786776532116858867887789987432', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h3', speaker: 'mensah', duration: 2.257, text: 'Granite\'s moving forward again. Thanks to you.', mouth: '0004433444455544333222244333444422', open: '0168867889789988666432687657887642', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h4', speaker: 'admiral', duration: 3.107, text: 'The ground line is holding. Well done, everyone.', mouth: '33334444444433333332220000000044444444333333333', open: '06778999988867556654432110000589989888777766532', emotion: 'warm'),
    ],
  ),
  'transmissionMission': CommsTriggerSpec(
    name: 'transmissionMission',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.h0', speaker: 'admiral', duration: 6.367, text: 'Pilot, Overwatch. The fleet is moving on your signal. What you do next decides this war.', mouth: '222444332222444443333300000003333444444444444443333333220000000444444444333333334444433333333300', open: '026887553216878887555321100006547878889989888887675766321100006889899998655325548886456635765321', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h1', speaker: 'lindqvist', duration: 4.991, text: 'Beacon here. Long-range scans show the brood massing ahead. Stay sharp.', mouth: '333333333220000000004444444444433333333443332233333220000000000033333332200', open: '057545555432110000178999988688877777766886664456566432110000002267767763211', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h2', speaker: 'admiral', duration: 3.794, text: 'Every sector you clear brings our people home. Thank you, pilot.', mouth: '333334444444444334443344444444333333322000000332224443322', open: '068778768758887678875789888674766777632110068674477885532', emotion: 'warm'),
    ],
  ),
  'transmissionMission.1': CommsTriggerSpec(
    name: 'transmissionMission.1',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.1.h0', speaker: 'admiral', duration: 4.372, text: 'Krybor\'s frontier is waiting. The outpost families are counting on you, pilot.', mouth: '000444444444444433333333333000000443333344444443344444443333333333', open: '017878885787678857667766553211006895786478998675578888887567775532', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.1.h1', speaker: 'kestrel', duration: 5.303, text: 'Krybor ridge ahead. Brood scouts everywhere. Keep your eyes moving.', mouth: '00044444444444333333332200022444433344433333334433332200000033344444455553333300', open: '00589979998999756677764211123789976478855537878877654321100067589999888987765321', emotion: 'calm'),
    ],
  ),
  'transmissionMission.2': CommsTriggerSpec(
    name: 'transmissionMission.2',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.2.h0', speaker: 'admiral', duration: 4.747, text: 'Next stop, the Ringfall belt. Break their supply line and the brood starves.', mouth: '334433333322000044444443332220000000003333333444444444433555333333222200', open: '058866477532110688995886663432110000686687747899988788856898776776444211', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.2.h1', speaker: 'lindqvist', duration: 4.3, text: 'Ringfall patrols are dense. Fly fast, don\'t linger in the rings.', mouth: '33443333222333333333222220000000443344433330000055553333333333222', open: '05896675444666554776444321100005897588865532178789887766777655421', emotion: 'calm'),
    ],
  ),
  'transmissionMission.3': CommsTriggerSpec(
    name: 'transmissionMission.3',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.3.h0', speaker: 'admiral', duration: 4.801, text: 'Ember Moon. Their foundries build every demon you\'ve fought. Shut them down.', mouth: '3344444444433220000000044444433443344444444444444444332200000004444433222', open: '0689899988775321100068589988866886588688789988885487653211015857888875321', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.3.h1', speaker: 'nomad', duration: 3.949, text: 'It gets hot over the Ember forges. Trust your instruments.', mouth: '333332222223344444444444444443322000000004433444443333332200', open: '067574433776689889999985899877642110000358766889985777654211', emotion: 'calm'),
    ],
  ),
  'transmissionMission.4': CommsTriggerSpec(
    name: 'transmissionMission.4',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.4.h0', speaker: 'admiral', duration: 3.413, text: 'The Hollow answers one command. Find it, and cut it.', mouth: '3334444444444334433333332200000044443330000333322200', open: '0678999888777768877777664211100689986532168667644211', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.4.h1', speaker: 'wisp', duration: 3.874, text: 'The Hollow\'s towers are broadcasting something. I\'ll keep listening.', mouth: '33334444334444433334433443333333333220000000004433333333222', open: '06678998668998767668767776776774576432110006868857777776421', emotion: 'calm'),
    ],
  ),
  'transmissionMission.5': CommsTriggerSpec(
    name: 'transmissionMission.5',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.5.h0', speaker: 'admiral', duration: 5.229, text: 'The Carrier. This is the heart of the brood. Everything we have is behind you.', mouth: '2233334433322000005555333333344333333344444400000000444444444444333333444333322', open: '0275477776642111004797658676589767676788885321100586887899977888576776787776532', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.5.h1', speaker: 'lindqvist', duration: 4.317, text: 'All fleet guns are at your disposal. Break the field, then the hatch.', mouth: '00000055533333333333333333334443333000044333444333000444444433322', open: '00000068866876577777857777678977753211688764787753216898786456532', emotion: 'calm'),
    ],
  ),
  'transmissionJunior': CommsTriggerSpec(
    name: 'transmissionJunior',
    priority: 3,
    cooldown: 120.0,
    ttl: 6.0,
    chance: 0.35,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionJunior.h0', speaker: 'pip', duration: 2.834, text: 'Captain? I just wanted to say I\'ve learned so much from you!', mouth: '2244444422233334444444444444444443333333222', open: '0487588642277878988789978988789987577765321', signature: true, emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h1', speaker: 'pip', duration: 2.61, text: 'Do you think I\'ll get my own ship someday? A real one?', mouth: '3344444444444444444444444444433344444422', open: '0588889887898997887798999853255688998632', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h2', speaker: 'sunny', duration: 3.464, text: 'Quick question. Can demons get sunburns? Asking for science.', mouth: '2222223333222244444444334444444220000003333444442200', open: '0474776555421788999888578899986421157747777899874321', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h3', speaker: 'rook', duration: 3.514, text: 'Betting pool says you\'ll beat my score. I put money on you!', mouth: '00044433333333333344444433444220004444444444444433300', open: '00689867766776786687788777897432158788789999998765321', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h4', speaker: 'sparrow', duration: 3.308, text: 'When this is over, first round\'s on me. Deal?', mouth: '33444334443333220004433444433355555220000000444422', open: '05899777776666421168857888877788985421100027898642', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h5', speaker: 'wisp', duration: 3.553, text: 'I logged your last run. Your dodge rate is ridiculous.', mouth: '334443344444333333220000000033444444444333333333333222', open: '068997688887757776321100000377899889977676853565555321', emotion: 'calm'),
      CommsLine(id: 'transmissionJunior.h6', speaker: 'nomad', duration: 3.358, text: 'Thirty years flying, and you still surprise me.', mouth: '000004444445555554433220000044444455533334444333222', open: '000068767899987478876432110378987478765748898665321', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h7', speaker: 'kestrel', duration: 3.028, text: 'Between us? You fly like a natural.', mouth: '2233334444433220000000000444444444444333444422', open: '0366547999865421110047746899999678888656887532', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h8', speaker: 'pip', duration: 3.377, text: 'I named my training drone after you! Is that weird?', mouth: '334444444444444444444444334444433300334455544444444', open: '068999989987889877888888678899875321578965578998532', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h9', speaker: 'anvil', duration: 3.186, text: 'Hydrate, pilot. Commander\'s orders. Well, my orders.', mouth: '000044444333333000444444443333000444444444332222', open: '000479888567653215899888886553215899878888754432', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h10', speaker: 'sunny', duration: 2.301, text: 'Fun fact: you\'re the brightest star in this sector.', mouth: '33444444222244444443344443333222200', open: '06885886421478789897688877566433211', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h11', speaker: 'rook', duration: 4.129, text: 'Admiral says I talk too much. Rook, out. Wait, one more thing.', mouth: '22333333333344333444433333222222444444444442222443344443333333', open: '04677667763578657885456666434215898537887453216885689995776532', emotion: 'teasing'),
    ],
  ),
  'terrainAhead': CommsTriggerSpec(
    name: 'terrainAhead',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.h0', speaker: 'march', duration: 3.375, text: 'Terrain change ahead. Convoy, adjust.', mouth: '222444444444443333322000000000555533222334443332222', open: '037899998788877676642111000278987765321678986654321', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.h1', speaker: 'kessler', duration: 2.028, text: 'Something big coming up ahead of us.', mouth: '0004444444444333444333333222200', open: '0248888863789757888667766444211', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.h2', speaker: 'voss', duration: 2.083, text: 'Eyes forward, the ground\'s changing.', mouth: '33444455544422223344433444443322', open: '06898578888742146789877888887532', emotion: 'calm'),
    ],
  ),
  'terrainAhead.ridge': CommsTriggerSpec(
    name: 'terrainAhead.ridge',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.ridge.h0', speaker: 'kessler', duration: 2.481, text: 'Rough ridge ahead, crawling over!', mouth: '22223344444444422000044444444555332200', open: '02587688787888642121789989885798664211', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.ridge.h1', speaker: 'march', duration: 4.088, text: 'Ridge line ahead. All tracks, climb and keep spacing.', mouth: '22444444444444333220000444444433322000444443333333333333332222', open: '04798888888877765321106898789855542116899986756766377656654321', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.ridge.h2', speaker: 'mensah', duration: 2.986, text: 'Granite\'s taking the high ridge. Slow and steady.', mouth: '000444333333333333333220022244555222222443333', open: '003788757777757776765421124689987435447886532', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.ridge.h3', speaker: 'voss', duration: 2.039, text: 'Big rocks ahead! Hold on to something!', mouth: '3333444334444422244444444443322', open: '0687898777888532789888887887632', emotion: 'excited'),
    ],
  ),
  'terrainAhead.valley': CommsTriggerSpec(
    name: 'terrainAhead.valley',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.valley.h0', speaker: 'voss', duration: 1.956, text: 'Valley\'s clear, rolling through!', mouth: '222444332244444334444444443333', open: '026888753479987557888746776532', emotion: 'excited'),
      CommsLine(id: 'terrainAhead.valley.h1', speaker: 'march', duration: 3.796, text: 'Low ground ahead. Watch the slopes on both sides.', mouth: '334444444443333332200000044433444444333344443334433322222', open: '058998888887767654211002788777887898664787886558876534421', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.valley.h2', speaker: 'kessler', duration: 3.993, text: 'Down into the valley. Keep your eyes on the high ground.', mouth: '000000004444555333344442200000333444444442224444333444333222', open: '000000268999888667688863211014765887899874478988757887676432', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.valley.h3', speaker: 'mensah', duration: 2.305, text: 'Nice and flat down here. Picking up speed.', mouth: '22233222223332222000044443334443333', open: '02465442687654343211477997637887532', emotion: 'warm'),
    ],
  ),
  'terrainAhead.canyon': CommsTriggerSpec(
    name: 'terrainAhead.canyon',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.canyon.h0', speaker: 'march', duration: 3.277, text: 'Canyon ahead. Single file, nobody stops.', mouth: '22244444433322222444444444444222444433333222222000', open: '04788886765542135899958999986426788776545421342111', emotion: 'stern'),
      CommsLine(id: 'terrainAhead.canyon.h1', speaker: 'kessler', duration: 3.629, text: 'Tight walls in this canyon. Perfect place for an ambush.', mouth: '3335555555553333333333220000000332224443344433333222222', open: '0576568999746676546776432110168564248987588767766444321', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.canyon.h2', speaker: 'voss', duration: 2.912, text: 'Lantern\'s lights on. It\'s dark between these cliffs.', mouth: '33444443344334444222223344433334444444433322', open: '05898887788778887421476689856578887479766532', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.canyon.h3', speaker: 'mensah', duration: 3.028, text: 'Echoes everywhere in here. Stay quiet, stay quick.', mouth: '2222444444444444333322200002244444222223332200', open: '0364899853778788765543211464479995435435653211', emotion: 'calm'),
    ],
  ),
  'terrainAhead.forest': CommsTriggerSpec(
    name: 'terrainAhead.forest',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.forest.h0', speaker: 'kessler', duration: 2.166, text: 'Tree line ahead! Clearing a path!', mouth: '333344444444422000044444332233322', open: '057788988997642112789998574476532', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.forest.h1', speaker: 'voss', duration: 2.578, text: 'Trees all over the trail. Cutting through!', mouth: '222444444444444334444422222222334455522', open: '036887647899888657888642137774578898642', emotion: 'excited'),
      CommsLine(id: 'terrainAhead.forest.h2', speaker: 'mensah', duration: 2.107, text: 'Forest ahead. They could be hiding in there.', mouth: '33444333332222233444444443332200', open: '05797565554214856888999887664321', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.forest.h3', speaker: 'march', duration: 2.552, text: 'Into the woods. Keep the convoy tight.', mouth: '334444444442233222222224444443333222200', open: '058878888764455323685878998987776444211', emotion: 'calm'),
    ],
  ),
  'terrainAhead.crystalField': CommsTriggerSpec(
    name: 'terrainAhead.crystalField',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.crystalField.h0', speaker: 'voss', duration: 3.489, text: 'Crystal field ahead. It\'s glowing. That\'s not normal.', mouth: '00000033444444442200333344444332200000033444444443333', open: '01777857888778863211676479988753211006866886898887532', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.crystalField.h1', speaker: 'kessler', duration: 2.398, text: 'Mind the crystals, they cut tracks like paper!', mouth: '222444444444333333334433332223333322', open: '047897787577658667458865874326657642', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.crystalField.h2', speaker: 'march', duration: 3.921, text: 'Crystal field. Slow speed, steer around the big ones.', mouth: '00003333333322000000004444444443322222444444444443332222000', open: '01687774577643211000257899857887532447899999988987764433211', emotion: 'stern'),
      CommsLine(id: 'terrainAhead.crystalField.h3', speaker: 'mensah', duration: 2.591, text: 'Beautiful. Creepy, but beautiful.', mouth: '222444455555224443333333444222233333222', open: '047896455421248987765326885446877455321', emotion: 'warm'),
    ],
  ),
  'terrainAhead.ruins': CommsTriggerSpec(
    name: 'terrainAhead.ruins',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'terrainAhead.ruins.h0', speaker: 'march', duration: 2.799, text: 'Old ruins ahead. Could be anything in there.', mouth: '555555544444433333330033333444334443333333', open: '047887789998876765532165877898567777655532', emotion: 'calm'),
      CommsLine(id: 'terrainAhead.ruins.h1', speaker: 'mensah', duration: 2.735, text: 'Ruins on the horizon. Granite will take point.', mouth: '000444444443333332220000444433333222233222', open: '016899988887777754321114799855367437876321', emotion: 'stern'),
      CommsLine(id: 'terrainAhead.ruins.h2', speaker: 'kessler', duration: 2.992, text: 'Rubble on the road. Pushing through the ruins!', mouth: '222445555444444444440000333443334444444422222', open: '026889986898888987532111677776578888998744421', emotion: 'urgent'),
      CommsLine(id: 'terrainAhead.ruins.h3', speaker: 'voss', duration: 3.252, text: 'These ruins are ancient. Who built all this?', mouth: '3344444444433444444333333000000000044444444433322', open: '0688778988875788888776453211000068789968978876532', emotion: 'calm'),
    ],
  ),
  'convoyClimbing': CommsTriggerSpec(
    name: 'convoyClimbing',
    priority: 3,
    cooldown: 25.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'convoyClimbing.h0', speaker: 'kessler', duration: 2.698, text: 'Climbing! Engines are screaming down here!', mouth: '00004444332200044444444333444444443333222', open: '01168998763211589898887757889989887766321', emotion: 'urgent'),
      CommsLine(id: 'convoyClimbing.h1', speaker: 'mensah', duration: 2.3, text: 'Uphill all the way. Granite doesn\'t mind.', mouth: '22222244455555443333344444333333222', open: '04743688689877887532689888667775321', emotion: 'teasing'),
      CommsLine(id: 'convoyClimbing.h2', speaker: 'voss', duration: 2.336, text: 'Steep climb! Lantern\'s holding on!', mouth: '223344444444444222244444444444433222', open: '025588547899876421688788788889876421', emotion: 'excited'),
      CommsLine(id: 'convoyClimbing.h3', speaker: 'march', duration: 2.829, text: 'Convoy climbing. Cover us while we\'re slow.', mouth: '2224444444433333322222444444444443344443333', open: '0257988886467776543237899987888877689876532', emotion: 'calm'),
    ],
  ),
  'convoyClearingVegetation': CommsTriggerSpec(
    name: 'convoyClearingVegetation',
    priority: 3,
    cooldown: 25.0,
    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'convoyClearingVegetation.h0', speaker: 'kessler', duration: 1.294, text: 'Clearing the tree line!', mouth: '00004444433344444222', open: '01478998876778986421', emotion: 'excited'),
      CommsLine(id: 'convoyClearingVegetation.h1', speaker: 'voss', duration: 2.916, text: 'Cutting through the brush! Branches everywhere!', mouth: '00333333555443332200044444444222223333443322', open: '01677656676887764211589988997432786777887632', emotion: 'excited'),
      CommsLine(id: 'convoyClearingVegetation.h2', speaker: 'mensah', duration: 2.156, text: 'Making our own road through these trees.', mouth: '222244444455554444433322233322000', open: '048688874589989975355543366532110', emotion: 'teasing'),
      CommsLine(id: 'convoyClearingVegetation.h3', speaker: 'march', duration: 2.753, text: 'Clearing a path. Keep moving, keep moving.', mouth: '000044433333322000000444444422225554433333', open: '011789866766532112377899888743778998766532', emotion: 'calm'),
    ],
  ),
  'convoyStuck': CommsTriggerSpec(
    name: 'convoyStuck',
    priority: 5,
    cooldown: 25.0,
    ttl: 3.0,
    mood: CommsMood.worried,
    group: 'ground',
    lines: [
